module cc_sync_wedge(input logic clk_i,rst_ni,clr_i,en_i,serial_i,output logic r_edge_o,f_edge_o,serial_o); logic q; always @(posedge clk_i or negedge rst_ni) if(!rst_ni) begin q<=0;serial_o<=0;r_edge_o<=0;f_edge_o<=0;end else if(clr_i) begin q<=0;serial_o<=0;r_edge_o<=0;f_edge_o<=0;end else if(en_i) begin serial_o<=q;r_edge_o<=serial_i&~q;f_edge_o<=~serial_i&q;q<=serial_i;end endmodule
module tb; logic clk_tx_i=0,clk_rx_i=0,rst_tx_ni,rst_rx_ni,edge_i,ack_tx_o,edge_o; string vcd; always #6 clk_tx_i=~clk_tx_i; always #8 clk_rx_i=~clk_rx_i; cc_edge_propagator_ack dut(.*); initial begin if(!$value$plusargs("VCD=%s",vcd))vcd="wave.vcd";$dumpfile(vcd);$dumpvars(0,tb);rst_tx_ni=0;rst_rx_ni=0;edge_i=0;#14;rst_tx_ni=1;rst_rx_ni=1;#19;edge_i=1;#12;edge_i=0;#24;edge_i=1;#12;edge_i=0;#33;rst_tx_ni=0;#13;rst_tx_ni=1;#35;$finish;end endmodule
